  for c in range(w):
   if grid[r][c]==2:
    neigh=[grid[rr][cc] for rr in range(max(0,r-1),min(h,r+2)) for cc in range(max(0,c-1),min(w,c+2)) if (rr,cc)!=(r,c)]
    if 3 in neigh or 2 in neigh:
     for rr in range(max(0,r-1),min(h,r+2)):
      for cc in range(max(0,c-1),min(w,c+2)):
       if grid[r][c]==2 and (3 in neigh):
        if grid[rr][cc]==3: out[rr][cc]=1
       else: out[rr][cc]=1
     out[r][c]=2
 return out
